package io.github.diodeme.ji.standalone;

import io.github.diodeme.ji.cli.LocalHostApplication;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

/** Executable standalone Host entry point; all runtime assets are Java classpath resources. */
public final class JiStandalone {
    private JiStandalone() {}

    public static void main(String[] args) throws Exception {
        if (args.length == 2 && "--health-check".equals(args[0])) {
            URI uri = URI.create(args[1]);
            HttpResponse<Void> response = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build()
                    .send(HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(10)).GET().build(),
                            HttpResponse.BodyHandlers.discarding());
            if (response.statusCode() != 200) throw new IllegalStateException("Host readiness check failed");
            return;
        }
        if (args.length != 0) throw new IllegalArgumentException("usage: ji-host [--health-check URI]");
        try (var host = LocalHostApplication.open(System.getenv())) {
            Runtime.getRuntime().addShutdownHook(Thread.ofPlatform().unstarted(host::close));
            System.out.println(host.launchUri());
            System.out.flush();
            Thread.currentThread().join();
        }
    }
}
